import { useState } from 'react';
import { getSourceCodenames } from '../data/sources';
import { airportGroups } from '../data/airportGroups';

export default function useNormalFlightSearch() {
  const [flightData, setFlightData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [selectedDateRange, setSelectedDateRange] = useState(null);
  const [selectedFlights, setSelectedFlights] = useState(null);
  const [pricingData, setPricingData] = useState(null);
  const [currentRoute, setCurrentRoute] = useState([]);

  const expandAirportGroup = (airport) => {
    return airportGroups[airport]?.split('/') || [airport];
  };

  const generateRoutePermutations = (segments) => {
    const expandedSegments = segments.map(segment => {
      if (airportGroups[segment]) {
        return expandAirportGroup(segment).sort();
      }
      return [segment];
    });

    const results = [];
    const generateCombinations = (current, index) => {
      if (index === expandedSegments.length) {
        // Create route string from adjacent pairs
        for (let i = 0; i < current.length - 1; i++) {
          results.push(`${current[i]}-${current[i + 1]}`);
        }
        return;
      }

      for (const airport of expandedSegments[index]) {
        generateCombinations([...current, airport], index + 1);
      }
    };

    generateCombinations([], 0);

    // Group routes by segment and sort each group
    const routeGroups = {};
    results.forEach(route => {
      const [from, to] = route.split('-');
      const groupKey = from; // Group by origin airport
      if (!routeGroups[groupKey]) {
        routeGroups[groupKey] = [];
      }
      routeGroups[groupKey].push(route);
    });

    // Sort routes within each group and combine
    const sortedRoutes = Object.values(routeGroups)
      .map(group => group.sort())
      .flat();

    return sortedRoutes;
  };

  const processFlightData = (data) => {
    // Group flights by date and route
    const flightsByDate = {};

    console.log('Raw API response:', data);
    console.log('Current route with groups:', currentRoute);

    data.forEach(flight => {
      const date = flight.date;
      const route = `${flight.originAirport}-${flight.destinationAirport}`;

      console.log('Processing flight:', { date, route });

      // Check if this route is a consecutive pair in the current route segments
      const isConsecutivePair = currentRoute.some((airport, index) => {
        if (index >= currentRoute.length - 1) return false;

        const fromAirport = airport;
        const toAirport = currentRoute[index + 1];

        // Expand airport groups for both from and to airports
        const fromAirports = airportGroups[fromAirport]?.split('/') || [fromAirport];
        const toAirports = airportGroups[toAirport]?.split('/') || [toAirport];

        // Check if the route matches any combination of expanded airports
        const isPair = fromAirports.some(from => 
          toAirports.some(to => 
            `${from}-${to}` === route
          )
        );

        console.log('Checking expanded pair:', { 
          fromAirports, 
          toAirports, 
          route, 
          isPair 
        });

        return isPair;
      });

      console.log('Is consecutive pair:', isConsecutivePair);

      // Only process consecutive pairs
      if (isConsecutivePair) {
        if (!flightsByDate[date]) {
          flightsByDate[date] = {};
        }

        flightsByDate[date][route] = {
          classes: {
            Y: { available: flight.YAvailable, direct: flight.YDirect, airlines: flight.YAirlines },
            W: { available: flight.WAvailable, direct: flight.WDirect, airlines: flight.WAirlines },
            J: { available: flight.JAvailable, direct: flight.JDirect, airlines: flight.JAirlines },
            F: { available: flight.FAvailable, direct: flight.FDirect, airlines: flight.FAirlines }
          }
        };
      }
    });

    console.log('Processed flight data:', flightsByDate);
    return flightsByDate;
  };

  const handleSearch = async (path, startDate, endDate) => {
    setIsLoading(true);
    setError(null);

    try {
      // Split the path into segments, handling both / and - separators
      const segments = path.split('-').map(segment => segment.trim());
      setCurrentRoute(segments);

      console.log('Search parameters:', { path, startDate, endDate });
      console.log('Current route segments:', segments);

      // Generate all possible route combinations
      const routePermutations = generateRoutePermutations(segments);
      console.log('Route permutations:', routePermutations);

      // Make parallel requests for all route permutations
      const responses = await Promise.all(
        routePermutations.map(route => 
          fetch(`${API_BASE_URL}/flights?route=${route}&startDate=${startDate}&endDate=${endDate}`, {
            headers: {
              'Authorization': `Bearer ${API_KEY}`
            }
          }).then(res => res.json())
        )
      );

      // Process all responses
      const allFlights = responses.flat();
      console.log('API response:', allFlights);

      // Process the flight data
      const processedData = processFlightData(allFlights);
      console.log('Processed data:', processedData);

      // Update the flight data state
      setFlightData(processedData);

      // Call the onSearch callback with the processed data
      if (onSearch) {
        onSearch(processedData);
      }
    } catch (err) {
      console.error('Error fetching flight data:', err);
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDateRangeSelect = (dateRange) => {
    setSelectedDateRange(dateRange);
  };

  const handleFlightSelect = (flights, pricing) => {
    setSelectedFlights(flights);
    setPricingData(pricing);
  };

  return {
    flightData,
    isLoading,
    handleSearch,
    errors,
    selectedDateRange,
    handleDateRangeSelect,
    selectedFlights,
    handleFlightSelect,
    pricingData
  };
}
